-- ============================================================================
-- CATALOGUE ÉLECTRONIQUE (Sénégal) : produits réellement en vente, harvest direct
-- (Firecrawl scrape des pages catégorie WooCommerce, nom/prix/photo tous issus de
-- la MÊME fiche produit source, cohérents par construction). Sources :
-- Soumari.com, Electromenager-Dakar.com, Promo.sn. Attribué au compte ADMIN.
-- Prix converti FCFA -> EUR (/655.957), cf. CLAUDE.md convention monétaire EUR.
-- Lot (565 produits, catégories : téléphones, électroménager, informatique,
-- téléviseurs, tablettes, high-tech, accessoires, énergie/solaire, sonorisation,
-- électronique, climatisation). Idempotent (skip si déjà présent pour ce vendeur+nom).
-- ============================================================================

do $$ begin
  if not exists (select 1 from public.profiles where role='admin') then
    raise exception 'Aucun compte admin (profiles.role=admin) — impossible d''attribuer le catalogue.';
  end if;
end $$;

drop table if exists _electronique_senegal_catalogue;
create temp table _electronique_senegal_catalogue(name text, category text, price_eur numeric, description text, image_url text, vendor_name text, source_url text);

-- Attribution à l'admin (le plus ancien si plusieurs).
with adm as (select id from public.profiles where role='admin' order by created_at asc limit 1)
select nc.name, nc.category, nc.price_eur, 5, nc.description, nc.image_url, (select id from adm), nc.vendor_name, true
  from _electronique_senegal_catalogue nc
 where not exists (select 1 from public.products p where p.vendor_id=(select id from adm) and p.name=nc.name);

-- Récap.
select count(*) as produits_inseres from _electronique_senegal_catalogue;
